import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int x = Integer.parseInt(st.nextToken());
        int pos = Integer.parseInt(st.nextToken());

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        int less = x - 1;
        int greater = n - x;

        int low = 0;
        int high = n;
        int cntLess = 0;
        int cntGreater = 0;

        while (low < high) {
            int mid = (low + high) / 2;
            if (mid <= pos) {
                if (mid < pos) {
                    cntLess++;
                }
                low = mid + 1;
            } else {
                cntGreater++;
                high = mid;
            }
        }

        if (cntLess > less || cntGreater > greater) {
            System.out.println(0);
            return;
        }

        long ans = 1;
        ans = ans * fact[less] % MOD;
        ans = ans * fact[greater] % MOD;

        long invLessPart = modInverse(fact[less - cntLess]);
        long invGreaterPart = modInverse(fact[greater - cntGreater]);

        ans = ans * invLessPart % MOD;
        ans = ans * invGreaterPart % MOD;

        System.out.println(ans);
    }

    static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long modInverse(long x) {
        return modPow(x, MOD - 2);
    }
}

