import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int x = Integer.parseInt(st.nextToken());
        int pos = Integer.parseInt(st.nextToken());

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        int less = x - 1;        // numbers < x
        int greater = n - x;     // numbers > x

        int low = 0, high = n;
        long ans = 1;

        while (low < high) {
            int mid = (low + high) / 2;
            if (mid == pos) {
                low = mid + 1;
            } else if (mid < pos) {
                // must place a number < x here
                if (less <= 0) {
                    ans = 0;
                    break;
                }
                ans = ans * less % MOD;
                less--;
                low = mid + 1;
            } else {
                // must place a number > x here
                if (greater <= 0) {
                    ans = 0;
                    break;
                }
                ans = ans * greater % MOD;
                greater--;
                high = mid;
            }
        }

        int remaining = less + greater; // remaining numbers to place freely
        ans = ans * fact[remaining] % MOD;

        System.out.println(ans);
    }
}

